def cache_sim(capacity, ttl, ops):
    cache = {}  # key -> value
    write_time = {}  # key -> time when written
    access_order = []  # list of keys in order of most recent access
    results = []

    def is_expired(key, current_time):
        if key not in write_time:
            return True
        return current_time >= write_time[key] + ttl

    def mark_accessed(key):
        if key in access_order:
            access_order.remove(key)
        access_order.append(key)

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Check if key already exists and is not expired
            if key in cache and not is_expired(key, t):
                # Key exists and is valid, just update it
                cache[key] = value
                write_time[key] = t
                mark_accessed(key)
            else:
                # Key is new or expired
                if key not in cache or is_expired(key, t):
                    # Need to add as a new entry
                    if len(cache) >= capacity:
                        # Evict least recently used
                        lru_key = None
                        for k in access_order:
                            if k in cache:
                                lru_key = k
                                break
                        if lru_key is not None:
                            del cache[lru_key]
                            del write_time[lru_key]
                            access_order.remove(lru_key)

                cache[key] = value
                write_time[key] = t
                mark_accessed(key)

        elif op[0] == 'get':
            _, t, key = op

            # Check if key exists and is not expired
            if key in cache and not is_expired(key, t):
                results.append(cache[key])
                mark_accessed(key)
            else:
                results.append(-1)

    return results

